import { defineComponent, ref } from 'vue';
import { paymentMtdAPOptions } from 'src/supplier/constant';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';

export default defineComponent({
  mixins: [],
  data() {
    return {
      docrowID: ref(),
      statusList: [] as any,
      QualityText: ref(),
      QualityConfirm: ref(false),
    };
  },
  methods: {
    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
    },
    goToDetails(row: any) {
      const id = row?.id as string;
      this.$router.push(`/invoice/details/${id}`);
    },
    statusColor(status: string) {
      if (status) {
        return getStatusColor(status.toLowerCase()) || 'primary';
      } else {
        return '';
      }
    },
    showPaymentMethodLabel(value: string) {
      let showLabel: string;
      const payment = paymentMtdAPOptions.find(
        (option) => option.value === value,
      ) as any;
      if (payment) {
        showLabel = payment.label;
      } else {
        showLabel = '';
      }
      return showLabel;
    },
    displayLastSixDigits(character: string) {
      let result;
      if (character && character.length > 6) {
        result = character.slice(-6);
      } else {
        result = character;
      }
      return result;
    },
    dateFields(date: string) {
      const field = [
        'invoice_date',
        'invoice_due_date',
        'discount_due_date',
        'payment_date',
      ];
      return field.some((key) => date.includes(key));
    },
    getClassesForColumn(column_name: string) {
      let styleClass = '';

      styleClass += column_name === 'document_id' ? ' text-primary ' : '';
      styleClass += column_name.includes('amount') ? ' text-right ' : '';

      return styleClass;
    },
  },
  setup() {
    return {};
  },
});
